[{"id":"11d42786","elType":"section","settings":{"structure":"22","padding":{"unit":"px","top":"72","right":"0","bottom":"124","left":"0","isLinked":false},"padding_mobile":{"unit":"px","top":"36","right":"0","bottom":"36","left":"0","isLinked":false}},"elements":[{"id":"d721a1c","elType":"column","settings":{"_column_size":66,"_inline_size":null},"elements":[{"id":"4abf46a0","elType":"widget","settings":{"title":"Rikki Borgelt en haar partner: liefde tussen Amsterdam en Italië","header_size":"h1"},"elements":[],"widgetType":"heading"},{"id":"1756f008","elType":"widget","settings":{"icon_list":[{"selected_icon":{"value":{"id":907,"url":"https://slaapkamerinspiratie.nl/wp-content/uploads/2024/10/mdi_calendar-today.svg"},"library":"svg"},"_id":"9a0fae1","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"Publicatie: 22 november 2023","show_icon":"custom","link":""}],"space_between":{"unit":"px","size":20,"sizes":[]},"icon_size":{"unit":"px","size":24,"sizes":[]},"_margin":{"unit":"px","top":"16","right":"0","bottom":"36","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"__globals__":{"text_color":"globals/colors?id=primary","icon_typography_typography":"globals/typography?id=text"}},"elements":[],"widgetType":"post-info"},{"id":"33ac323c","elType":"widget","settings":{"source":"custom","author_avatar":{"id":912,"url":"https://slaapkamerinspiratie.nl/wp-content/uploads/2024/10/undefined-2024-10-31T090156.319.jpeg","alt":"undefined - 2024-10-31T090156.319","source":"library","size":""},"author_name":"Michael","author_name_tag":"span","author_bio":"Ik ben Michael, een schrijver die graag artikelen schrijft over onderwerpen die mensen boeien en informeren. Het plezier in schrijven ontdekte ik al vroeg, en sindsdien is het mijn passie geworden om complexe onderwerpen op een begrijpelijke en aantrekkelijke manier uit te leggen. In mijn werk probeer ik altijd een balans te vinden tussen nuttige informatie en een vlotte, toegankelijke stijl. Ik schrijf over uiteenlopende thema’s, van actualiteit tot lifestyle, en geniet van het proces om van elk artikel iets waardevols te maken. Mijn doel is om lezers iets mee te geven waar ze echt iets aan hebben.






