","link_text":"All Posts","image_vertical_align":"middle","image_size":{"unit":"px","size":100,"sizes":[]},"image_border_radius":{"unit":"px","size":100,"sizes":[]},"name_color":"#000000","name_typography_typography":"custom","name_typography_font_family":"Inter","name_typography_font_size":{"unit":"px","size":16,"sizes":[]},"name_typography_font_size_mobile":{"unit":"px","size":14,"sizes":[]},"name_typography_font_weight":"700","bio_typography_typography":"custom","bio_typography_font_family":"Inter","bio_typography_font_size":{"unit":"px","size":11,"sizes":[]},"bio_typography_font_size_mobile":{"unit":"px","size":14,"sizes":[]},"bio_typography_font_weight":"400","_margin":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"36","right":"0","bottom":"0","left":"0","isLinked":false},"__globals__":{"name_color":"globals/colors?id=primary","name_typography_typography":""}},"elements":[],"widgetType":"author-box"},{"id":"167c3563","elType":"widget","settings":{"editor":"<p data-start="800" data-end="1160">Yvonne Coldeweijer staat bekend als een uitgesproken mediapersoonlijkheid die geen blad voor de mond neemt. Maar achter haar publieke persona schuilt een vrouw die haar privéleven zorgvuldig afschermt. Toch is er de afgelopen tijd meer bekend geworden over haar relatie met Max Vieleers, de man met wie ze niet alleen haar leven deelt, maar ook een zoon heeft.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"1068363","elType":"widget","settings":{"html":"<blockquote class="instagram-media" data-instgrm-captioned data-instgrm-permalink="https://www.instagram.com/p/C_0OJC7IgXc/?utm_source=ig_embed&amp;utm_campaign=loading" data-instgrm-version="14" style=" background:#FFF; border:0; border-radius:3px; box-shadow:0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width:540px; min-width:326px; padding:0; width:99.375%; width:-webkit-calc(100% - 2px); width:calc(100% - 2px);"><div styl