"},"elements":[],"widgetType":"heading"},{"id":"56f879e3","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Jill Helena is niet alleen een getalenteerde zangeres, maar ook een voorbeeld van doorzettingsvermogen, moed en authenticiteit. Haar carrière en persoonlijke leven tonen aan hoe belangrijk het is om trouw te blijven aan je dromen, zelfs als je te maken krijgt met tegenslagen. Of het nu in de muziek of in de rechtszaal is, Jill blijft een krachtige vrouw die haar stem gebruikt om anderen te inspireren en verandering teweeg te brengen.</span></p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"298f6a2a","elType":"column","settings":{"_column_size":33,"_inline_size":null,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"3e87863a","elType":"widget","settings":{"title":"Inhoud ","html_tag":"div","exclude_headings_by_selector":[],"marker_view":"bullets","icon":{"value":"","library":""},"border_width":{"unit":"px","size":0,"sizes":[]},"padding":{"unit":"px","size":0,"sizes":[]},"header_separator_width":{"unit":"px","size":0,"sizes":[]},"custom_css":"selector .elementor-toc__header {
