","header_size":"h1"},"elements":[],"widgetType":"heading"},{"id":"4f85cf57","elType":"widget","settings":{"icon_list":[{"selected_icon":{"value":{"id":907,"url":"https://slaapkamerinspiratie.nl/wp-content/uploads/2024/10/mdi_calendar-today.svg"},"library":"svg"},"_id":"9a0fae1","custom_date_format":"F j, Y","custom_time_format":"g:i a","custom_text":"Publicatie: 22 november 2023","show_icon":"custom","link":""}],"space_between":{"unit":"px","size":20,"sizes":[]},"icon_size":{"unit":"px","size":24,"sizes":[]},"_margin":{"unit":"px","top":"16","right":"0","bottom":"36","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":false},"__globals__":{"text_color":"globals/colors?id=primary","icon_typography_typography":"globals/typography?id=text"}},"elements":[],"widgetType":"post-info"},{"id":"5d4f6429","elType":"widget","settings":{"source":"custom","author_avatar":{"id":912,"url":"https://slaapkamerinspiratie.nl/wp-content/uploads/2024/10/undefined-2024-10-31T090156.319.jpeg","alt":"Michael","source":"library","size":""},"author_name":"Michael","author_name_tag":"span","author_bio":"Ik ben Michael, een schrijver die graag artikelen schrijft over onderwerpen die mensen boeien en informeren. Het plezier in schrijven ontdekte ik al vroeg, en sindsdien is het mijn passie geworden om complexe onderwerpen op een begrijpelijke en aantrekkelijke manier uit te leggen. In mijn werk probeer ik altijd een balans te vinden tussen nuttige informatie en een vlotte, toegankelijke stijl. Ik schrijf over uiteenlopende thema’s, van actualiteit tot lifestyle, en geniet van het proces om van elk artikel iets waardevols te maken. Mijn doel is om lezers iets mee te geven waar ze echt iets aan hebben.","link_text":"All Posts","image_vertical_align":"middle","image_size":{"unit":"px","size":100,"sizes":[]},"image_border_radius":{"unit":"px","size":100,"sizes":[]},"name_color":"#000000","name_typography_typography":"custom","name_typography_font_family":"Inter","name_typography_font_size":{"unit":"px","size":16,"sizes":[]},"name_typography_font_size_mobile":{"unit":"px","size":14,"sizes":[]},"name_typography_font_weight":"700","bio_typography_typography":"custom","bio_typography_font_family":"Inter","bio_typography_font_size":{"unit":"px","size":11,"sizes":[]},"bio_typography_font_size_mobile":{"unit":"px","size":14,"sizes":[]},"bio_typography_font_weight":"400","_margin":{"unit":"px","top":"10","right":"0","bottom":"0","left":"0","isLinked":false},"_margin_mobile":{"unit":"px","top":"36","right":"0","bottom":"0","left":"0","isLinked":false},"__globals__":{"name_color":"globals/colors?id=primary","name_typography_typography":""}},"elements":[],"widgetType":"author-box"},{"id":"25cd0cd9","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Megan Desaever, bekend van haar deelname aan </span><i><span style="font-weight: 400;">Temptation Island</span></i><span style="font-weight: 400;"> en </span><i><span style="font-weight: 400;">Ex on the Beach</span></i><span style="font-weight: 400;">, heeft haar ware liefde gevonden in de Britse zakenman Oliver Richards. Hun relatie begon in juni 2024 op Ibiza en ontwikkelde zich snel. In september 2024 kondigde het stel hun verloving aan, en in november gaven ze elkaar het jawoord in Las Vegas.</span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"5d1a6c0a","elType":"widget","settings":{"title":"Oliver Richards: wie is hij?
"},"elements":[],"widgetType":"heading"},{"id":"199d914","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Oliver Richards is een 30-jarige Britse ondernemer die aan het hoofd staat van negen internationale bedrijven. Hij groeide op in een moeilijke omgeving in Hampshire, waar hij besloot zijn leven een andere wending te geven en zich omhoog te werken. Zijn verleden heeft hem gevormd tot de man die hij nu is, en hij deelt zijn leven met Megan.</span></p>"},"elements":[],"widgetType":"text-editor"},{"id":"04e0f5e","elType":"widget","settings":{"html":"<blockquote class="instagram-media" data-instgrm-captioned data-instgrm-permalink="https://www.instagram.com/p/C8nLaBbNvgh/?utm_source=ig_embed&amp;utm_campaign=loading" data-instgrm-version="14" style=" background:#FFF; border:0; border-radius:3px; box-shadow:0 0 1px 0 rgba(0,0,0,0.5),0 1px 10px 0 rgba(0,0,0,0.15); margin: 1px; max-width:540px; min-width:326px; padding:0; width:99.375%; width:-webkit-calc(100% - 2px); width:calc(100% - 2px);"><div style="padding:16px;"> <a href="https://www.instagram.com/p/C8nLaBbNvgh/?utm_source=ig_embed&amp;utm_campaign=loading" style=" background:#FFFFFF; line-height:0; padding:0 0; text-align:center; text-decoration:none; width:100%;" target="_blank"> <div style=" display: flex; flex-direction: row; align-items: center;"> <div style="background-color: #F4F4F4; border-radius: 50%; flex-grow: 0; height: 40px; margin-right: 14px; width: 40px;"></div> <div style="display: flex; flex-direction: column; flex-grow: 1; justify-content: center;"> <div style=" background-color: #F4F4F4; border-radius: 4px; flex-grow: 0; height: 14px; margin-bottom: 6px; width: 100px;"></div> <div style=" background-color: #F4F4F4; border-radius: 4px; flex-grow: 0; height: 14px; width: 60px;"></div></div></div><div style="padding: 19% 0;"></div> <div style="display:block; height:50px; margin:0 auto 12px; width:50px;"><svg width="50px" height="50px" viewBox="0 0 60 60" version="1.1" xm