"},"elements":[],"widgetType":"heading"},{"id":"1fe821e6","elType":"widget","settings":{"editor":"<p><span style="font-weight: 400;">Iris Enthoven heeft zich bewezen als een invloedrijke persoonlijkheid in de Nederlandse media. Naast haar werk bij Radio 538 en haar podcasts, heeft ze ook deelgenomen aan populaire programma's zoals </span><i><span style="font-weight: 400;">Expeditie Robinson</span></i><span style="font-weight: 400;">. Ze staat bekend om haar openheid en authenticiteit, zowel in haar professionele werk als in haar persoonlijke leven.</span></p>"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7128b015","elType":"column","settings":{"_column_size":33,"_inline_size":null,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"59c7139c","elType":"widget","settings":{"title":"Inhoud ","html_tag":"div","exclude_headings_by_selector":[],"marker_view":"bullets","icon":{"value":"","library":""},"border_width":{"unit":"px","size":0,"sizes":[]},"padding":{"unit":"px","size":0,"sizes":[]},"header_separator_width":{"unit":"px","size":0,"sizes":[]},"custom_css":"selector .elementor-toc__header {
