F4; border-radius: 4px; flex-grow: 0; height: 14px; margin-bottom: 6px; width: 224px;"></div> <div style=" background-color: #F4F4F4; border-radius: 4px; flex-grow: 0; height: 14px; width: 144px;"></div></div></a><p style=" color:#c9c8cd; font-family:Arial,sans-serif; font-size:14px; line-height:17px; margin-bottom:0; margin-top:8px; overflow:hidden; padding:8px 0 7px; text-align:center; text-overflow:ellipsis; white-space:nowrap;"><a href="https://www.instagram.com/p/DGIYYoPsIzA/?utm_source=ig_embed&amp;utm_campaign=loading" style=" color:#c9c8cd; font-family:Arial,sans-serif; font-size:14px; font-style:normal; font-weight:normal; line-height:17px; text-decoration:none;" target="_blank">Een bericht gedeeld door Viktor Brand (@viktor_brand)</a></p></div></blockquote>
<script async src="//www.instagram.com/embed.js"></script>"},"elements":[],"widgetType":"html"},{"id":"3736ba9","elType":"widget","settings":{"title":"Professionele achtergronden
"},"elements":[],"widgetType":"heading"},{"id":"514a522","elType":"widget","settings":{"editor":"<p>Terwijl Viktor een prominente televisiepersoonlijkheid is, heeft André een carrière in de wetenschap. Hij werkt als chemicus en ontwikkelt medicijnen voor een groot Amerikaans bedrijf. Deze verschillende professionele achtergronden dragen bij aan de dynamiek van hun relatie, waarbij ze elkaar op verschillende vlakken aanvullen.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"dbe1bcc","elType":"widget","settings":{"title":"Gezamenlijk leven en toekomstplannen
"},"elements":[],"widgetType":"heading"},{"id":"5169799c","elType":"widget","settings":{"editor":"<p>Het stel deelt niet alleen hun dagelijkse leven, maar ook hun toekomstplannen. Viktor heeft ooit aangegeven dat hij droomt van een leven op een berg in Spanje, samen met André en een groep geadopteerde honden, terwijl ze een kleine bed &amp; breakfast runnen.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"7e48795f","elType":"widget","settings":{"title":"Hun geliefde hond Tapas
"},"elements":[],"widgetType":"heading"},{"id":"b5e39c1","elType":"widget","settings":{"editor":"<p>Hoewel Viktor en André geen kinderen hebben, speelde hun hond Tapas een belangrijke rol in hun leven. Tapas, geadopteerd uit Spanje, werd beschouwd als een volwaardig lid van het gezin. Helaas overleed Tapas in juni 2023, wat een groot verlies was voor het stel.</p>"},"elements":[],"widgetType":"text-editor"},{"id":"1f251a3","elType":"widget","settings":{"title":"Conclusie"},"elements":[],"widgetType":"heading"},{"id":"1fe821e6","elType":"widget","settings":{"editor":"<p>De relatie tussen Viktor Brand en André Koelewijn is een mooi voorbeeld van een langdurige en liefdevolle samenwerking. Hun wederzijds respect, gedeelde interesses en gezamenlijke dromen vormen de basis van hun sterke band. Hun verhaal biedt inspiratie voor velen die streven naar een harmonieuze en ondersteunende relatie.</p><div class="abh_box abh_box_down abh_box_business"> </div>"},"elements":[],"widgetType":"text-editor"}],"isInner":false},{"id":"7128b015","elType":"column","settings":{"_column_size":33,"_inline_size":null,"margin":{"unit":"px","top":"0","right":"0","bottom":"0","left":"40","isLinked":false},"margin_tablet":{"unit":"px","top":"0","right":"0","bottom":"0","left":"0","isLinked":true}},"elements":[{"id":"59c7139c","elType":"widget","settings":{"title":"Inhoud ","html_tag":"div","exclude_headings_by_selector":[],"marker_view":"bullets","icon":{"value":"","library":""},"border_width":{"unit":"px","size":0,"sizes":[]},"padding":{"unit":"px","size":0,"sizes":[]},"header_separator_width":{"unit":"px","size":0,"sizes":[]},"custom_css":"selector .elementor-toc__header {
